import{_ as s,o as t,c as a,a3 as n}from"./chunks/framework.BlfGB29P.js";const i="/images/logic-studio/user-guide/blocks-a-en.png",u=JSON.parse('{"title":"Blocks A","description":"","frontmatter":{},"headers":[],"relativePath":"en/projects/logic-studio/user-guide/blocks-a.md","filePath":"en/projects/logic-studio/user-guide/blocks-a.md","lastUpdated":1795870063000}'),o={name:"en/projects/logic-studio/user-guide/blocks-a.md"};function r(l,e,c,d,h,p){return t(),a("div",null,[...e[0]||(e[0]=[n(`<h1 id="blocks-a" tabindex="-1">Blocks A <a class="header-anchor" href="#blocks-a" aria-label="Permalink to &quot;Blocks A&quot;">​</a></h1><p><strong>Workspace from 0.1.137:</strong> Dotted grid without snapping. The mouse wheel pans the view; Shift + wheel pans horizontally. Ctrl + wheel zooms. Zoom buttons and pinch are also available. Saved block positions are preserved.</p><p><strong>0.1.136 scope:</strong> The new state trigger and automatic confirmed write order apply to <strong>Blocks JS</strong>. Blocks A YAML retains its native event bridge. Both sensor variants remain available; permissions and saved projects are retained. Field commits without Enter and <strong>Clear log</strong> are shared Studio UI features. 99 local tests passed; Additionally live-tested on 28 November 2026 after a full backup on HA 2026.11.3 (.193, port 80): Blocks JS state/attribute branches, writing before debug, decimal input without Enter, the previous-code warning and log clearing. Test values restored, projects and permissions preserved; examples stopped. <a href="./../#zustandstrigger-reihenfolge">Live test evidence</a>.</p><p><strong>0.1.135:</strong> All 51 direct entity fields in 285 registered Blocks A/JS blocks were checked for HA selection. The new multi-selector and compact change triggers affect Blocks JS. Existing structured HA target fields, lists and saved mappings in Blocks A are retained. 68 Node tests and 12 server tests passed; no HA live test for this version.</p><h2 id="sensorzustand-setzen" tabindex="-1">Set sensor state <a class="header-anchor" href="#sensorzustand-setzen" aria-label="Permalink to &quot;Set sensor state {#sensorzustand-setzen}&quot;">​</a></h2><h3 id="sensor-dezimalzahl" tabindex="-1">Enter decimal values directly <a class="header-anchor" href="#sensor-dezimalzahl" aria-label="Permalink to &quot;Enter decimal values directly {#sensor-dezimalzahl}&quot;">​</a></h3><p>Since <strong>0.1.134</strong>: Choose <strong>System → Set sensor state · Decimal number</strong>, select a sensor and enter the value directly. The default is <code>0.5</code>; enter values such as <code>33.25</code> using a decimal point. Values are not rounded to integers and survive saving and reloading. The existing value-input block remains available. WRITE permission and sensor attributes are handled in the same way. Blocks A requires the running Studio app.</p><p><strong>Verified:</strong> 72 local tests plus, after backup on HA 2026.11.3, <code>0.5</code> and <code>33.25</code> through Blocks JS Play and the generated and inspected Blocks A event data. Both fields were confirmed after reloading; settings and attributes were retained.</p><p>From <strong>0.1.133</strong>, <strong>System</strong> includes <strong>Set sensor state</strong>:</p><ol><li>Select an existing <code>sensor.*</code> using HA-style entity selection.</li><li>Connect a number, text or calculation block to the value input (state length: at most 255 characters).</li><li>Permit this sensor under <strong>WRITE – individual targets</strong> (<code>runtime_write_entities</code>) in the app configuration. Preserve existing entries. READ alone is insufficient.</li><li>Choose <strong>Check blocks → Open as HA YAML</strong>. Review and install the automation in Home Assistant yourself.</li></ol><p>Example generated action:</p><div class="language-yaml vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">yaml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">actions</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  - </span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">event</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">logic_studio_set_sensor_state</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">    event_data</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">      entity_id</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">sensor.example</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">      state</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">43</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br></div></div><p>The running Studio app receives the event and checks WRITE. Without the app, it is not processed. No general EVENT permission is required for this internal input. Errors appear in the app log; successfully firing an event does not confirm that the write succeeded.</p><p>The block retains unit, device class and other attributes. It behaves like <strong>Developer Tools → States</strong>, controls no device and creates no persistent sensor. The owning integration may replace the value later. YAML previews perform no writes.</p><h2 id="first-example" tabindex="-1">First example <a class="header-anchor" href="#first-example" aria-label="Permalink to &quot;First example&quot;">​</a></h2><p>The example turns on a hallway light when the motion sensor changes to <code>on</code>.</p><ol><li>Choose <strong>New project → Blocks A</strong> and name the project. The workspace contains an <strong>Automation</strong> block.</li><li>Open <strong>Triggers</strong> and drag the state trigger into <strong>When</strong>. The screenshot uses <code>binary_sensor.flur_bewegung</code> and the state <code>on</code>. Select your own test helper or sensor.</li><li>Open <strong>Actions</strong> and drag a switch action into <strong>Then</strong>. The example uses <code>light.flur</code> and <strong>turn on</strong>. You can target a second test helper instead. Leave <strong>Only if</strong> empty for this example.</li><li>Click the flag icon to check the blocks. When the check passes, choose <strong>Open as HA YAML</strong> and review <code>triggers</code> and <code>actions</code> before exporting.</li></ol><p><a href="/images/logic-studio/user-guide/blocks-a-en.png"><img src="`+i+'" alt="Blocks A with a state trigger in When and a switch action in Then"></a></p><h2 id="features" tabindex="-1">Features <a class="header-anchor" href="#features" aria-label="Permalink to &quot;Features&quot;">​</a></h2><h3 id="palette-and-connectors" tabindex="-1">Palette and connectors <a class="header-anchor" href="#palette-and-connectors" aria-label="Permalink to &quot;Palette and connectors&quot;">​</a></h3><p>Pick blocks by their role. Connector shapes indicate where a value or an action fits.</p><h3 id="triggers-and-conditions" tabindex="-1">Triggers and conditions <a class="header-anchor" href="#triggers-and-conditions" aria-label="Permalink to &quot;Triggers and conditions&quot;">​</a></h3><p>A trigger starts the automation. A condition can check whether the other helper is off.</p><h3 id="actions" tabindex="-1">Actions <a class="header-anchor" href="#actions" aria-label="Permalink to &quot;Actions&quot;">​</a></h3><p>Stack actions in the order they should run.</p><h3 id="ha-selectors" tabindex="-1">HA selectors <a class="header-anchor" href="#ha-selectors" aria-label="Permalink to &quot;HA selectors&quot;">​</a></h3><p>Choose entities, actions, devices, areas, labels or floors. Check the corresponding ID in YAML.</p><h3 id="ha-yaml-draft" tabindex="-1">HA-YAML draft <a class="header-anchor" href="#ha-yaml-draft" aria-label="Permalink to &quot;HA-YAML draft&quot;">​</a></h3><p>Open the generated automation as a draft that identifies its source project.</p><h3 id="export" tabindex="-1">Export <a class="header-anchor" href="#export" aria-label="Permalink to &quot;Export&quot;">​</a></h3><p>Check the YAML and use it in HA. Test the trigger and inspect the automation trace there.</p><h2 id="if-something-goes-wrong" tabindex="-1">If something goes wrong <a class="header-anchor" href="#if-something-goes-wrong" aria-label="Permalink to &quot;If something goes wrong&quot;">​</a></h2><p>If a selector is empty, check the connected HA system for matching entries.</p>',33)])])}const k=s(o,[["render",r]]);export{u as __pageData,k as default};
